class Solution:
    def maxSumAfterPartitioning(self, arr: list[int], k: int) -> int:
        n = len(arr)
        def dfs(i: int) -> int:
            if i == n:
                return 0
            best = cur_max = 0
            for j in range(i, min(n, i + k)):
                cur_max = max(cur_max, arr[j])
                best = max(best, cur_max * (j - i + 1) + dfs(j + 1))
            return best
        return dfs(0)

