class Solution:
    def maxSumAfterPartitioning(self, arr: list[int], k: int) -> int:
        n = len(arr)
        dp = [0] * (n + 1)
        for i in range(1, n + 1):
            cur_max = 0
            for length in range(1, min(k, i) + 1):
                cur_max = max(cur_max, arr[i - length])
                dp[i] = max(dp[i], dp[i - length] + cur_max * length)
        return dp[n]

